size_t vfs_dax_splice_lock_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void vfs_dax_splice_lock_init(void) {
    g_online = true;
    kprintf("[FS/VFS-DAX] Persistent Memory FS-DAX + OFD Byte-Range Locks + fanotify + renameat2 (%lu rules)\n", (unsigned long)vfs_dax_splice_lock_db_size());
}

bool vfs_dax_splice_lock_selftest(void) {
    return g_online && vfs_dax_splice_lock_db_size() >= 3400;
}
